#!/usr/bin/env perl
use strict;
use warnings;
use Encode qw(decode encode FB_CROAK LEAVE_SRC);
use JSON::PP;
my $rules = decode_json(do { local $/; <DATA> });
-d 'Assets' or die "Run this from the Unity project folder containing Assets.\n";
for my $path (sort keys %$rules) {
    unless (-f $path) { print "Skipped (missing): $path\n"; next; }
    open my $in, '<:raw', $path or die "$path: $!";
    my $raw = do { local $/; <$in> };
    close $in;
    my ($s,$enc);
    for my $candidate ('UTF-8','cp949') {
        $s = eval { decode($candidate,$raw,FB_CROAK|LEAVE_SRC) };
        if (defined $s) { $enc=$candidate; last; }
    }
    unless ($enc && index($raw,"\0") < 0 && encode($enc,$s,FB_CROAK|LEAVE_SRC) eq $raw) { print "Skipped (encoding): $path\n"; next; }
    my $n=0;
    my $block=0;
    $s =~ s{^([^\r\n]+)}{
        my $line=$1;
        (my $key=$line)=~s/^\s+|\s+$//g;
        $block=1 if $key =~ m{^/\*};
        my $note=$block ? undef : $rules->{$path}{$key};
        $block=0 if $key =~ m{\*/};
        if (defined $note) { ++$n; $line .= $note; }
        $line;
    }gme;
    if ($n) {
        my $bytes=encode($enc,$s,FB_CROAK|LEAVE_SRC);
        my $temp="$path.comments-tmp";
        use Fcntl qw(O_WRONLY O_CREAT O_EXCL);
        sysopen my $out,$temp,O_WRONLY|O_CREAT|O_EXCL or die "$temp: $!";
        binmode $out; print {$out} $bytes or die "$temp: $!"; close $out or die "$temp: $!";
        rename $temp,$path or die "$path: $!";
    }
    print "$path: $n comments added\n";
}
