5d0 \uc788\ub294 UI\ub85c \ud5a5\ud558\ub294 \ub9c8\uc6b0\uc2a4 \uc785\ub825\uc744 \uac00\ub85c\ucc44\uc9c0 \uc54a\uac8c \ud55c\ub2e4.", "private void ClearCard()": "  // \ud604\uc7ac \ud45c\uc2dc \uc911\uc778 \ubbf8\ub9ac\ubcf4\uae30\ub97c \uc228\uae30\uace0 \ubcf5\uc81c\ud55c \uc624\ube0c\uc81d\ud2b8\ub97c \uc81c\uac70\ud55c\ub2e4."}, "Assets/03.Scripts/CardData.cs": {"public int damage;": "  // \uc774 \uce74\ub4dc\ub97c \uc0ac\uc6a9\ud588\uc744 \ub54c \uc0c1\ub300 HP\uc5d0\uc11c \ube84 \ud53c\ud574\ub7c9\uc774\ub2e4."}, "Assets/03.Scripts/BattleTurnManager.cs": {"private void Awake()": "  // \uc804\ud22c\uac00 \uc2dc\uc791\ub420 \ub54c \uce74\ub4dc\uac00 \ucc3e\uc544 \uc4f8 \ud134 \uad00\ub9ac\uc790\ub97c \ub4f1\ub85d\ud55c\ub2e4.", "Instance = this;": "  // this\ub294 \uc9c0\uae08 \uc2e4\ud589 \uc911\uc778 \ucef4\ud3ec\ub10c\ud2b8 \uc790\uc2e0\uc774\ub2e4. \ub2e4\ub978 \uc2a4\ud06c\ub9bd\ud2b8\uac00 Instance\ub85c \uc774 \uad00\ub9ac\uc790\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4.", "public bool TryUsePlayerCard(CardData card)": "  // \uce74\ub4dc \uc0ac\uc6a9 \uc870\uac74\uc744 \uac80\uc0ac\ud558\uace0 \uacf5\uaca9\uc774 \uc2dc\uc791\ub418\uba74 true\ub97c \ub3cc\ub824\uc900\ub2e4.", "CanPlayCard = false;": "  // \uc801 \ud589\ub3d9\uc774 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \ucd94\uac00 \uce74\ub4dc \uc785\ub825\uc744 \uc7a0\uac00 \uc911\ubcf5 \uacf5\uaca9\uc744 \ub9c9\ub294\ub2e4.", "enemy.TakeDamage(card.damage);": "  // \uc120\ud0dd\ud55c \uce74\ub4dc \ub370\uc774\ud130\uc758 \ud53c\ud574\ub7c9\ub9cc\ud07c \ud604\uc7ac \uc801\uc758 HP\ub97c \uc904\uc778\ub2e4.", "StartCoroutine(EnemyTurn(enemy, skills));": "  // \ubc29\uae08 \uacf5\uaca9\ud55c \uc801\uacfc \uadf8 \uc801\uc758 \uae30\uc220 \ubaa9\ub85d\uc744 \ub118\uaca8 \ubc18\uaca9 \uc21c\uc11c\ub97c \uc2dc\uc791\ud55c\ub2e4.", "private IEnumerator EnemyTurn(": "  // \ud50c\ub808\uc774\uc5b4\uc758 \uacf5\uaca9 \uacb0\uacfc\ub97c \ud655\uc778\ud558\uace0 \uc0b4\uc544 \uc788\ub294 \uc801\uc758 \ud589\ub3d9\uc744 \uc9c4\ud589\ud558\ub294 \ucf54\ub8e8\ud2f4\uc774\ub2e4.", "ui.ShowCard(null);": "  // \uc801\uc774 \uc4f0\ub7ec\uc84c\uc73c\ubbc0\ub85c \uc774\uc804\uc5d0 \ud45c\uc2dc\ud55c \ub2e4\uc74c \ud589\ub3d9 \uce74\ub4dc\ub97c \uc9c0\uc6b4\ub2e4.", "yield return new WaitForSeconds(enemyActionDelay);": "  // \ud50c\ub808\uc774\uc5b4 \uacf5\uaca9\uacfc \uc801 \ubc18\uaca9\uc774 \uad6c\ubd84\ub418\uc5b4 \ubcf4\uc774\ub3c4\ub85d \uc124\uc815\ud55c \uc2dc\uac04\ub9cc\ud07c \uae30\ub2e4\ub9b0\ub2e4.", "player.TakeDamage(enemyCard.damage);": "  // \uc801\uc774 \uc608\uace0\ud55c \uce74\ub4dc\uc758 \ud53c\ud574\ub7c9\uc744 \ud50c\ub808\uc774\uc5b4\uc5d0\uac8c \uc801\uc6a9\ud55c\ub2e4.", "skills.PrepareNextCard();": "  // \uc0b4\uc544 \uc788\ub294 \uc801\uc774 \ub2e4\uc74c \ucc28\ub840\uc5d0 \uc4f8 \uce74\ub4dc\ub97c \ub2e4\uc2dc \ubf51\uc544 \uc608\uace0\ud55c\ub2e4.", "CanPlayCard = true;": "  // \uc801 \ud589\ub3d9\uc744 \ub9c8\ucce4\uc73c\ubbc0\ub85c \ud50c\ub808\uc774\uc5b4\uac00 \ub2e4\uc2dc \uce74\ub4dc\ub97c \ub204\ub97c \uc218 \uc788\ub2e4.", "private void OnDestroy()": "  // \uc774 \ucef4\ud3ec\ub10c\ud2b8\uac00 \ud30c\uad34\ub420 \ub54c Unity\uac00 \ud638\ucd9c\ud558\ub294 \uc815\ub9ac \ud568\uc218\ub2e4.", "if (Instance == this)": "  // \uacf5\uc720 \ucc38\uc870\uac00 \uc544\uc9c1 \uc774 \uad00\ub9ac\uc790\ub97c \uac00\ub9ac\ud0ac \ub54c\ub9cc \ube44\uc6b4\ub2e4.", "Instance = null;": "  // \ub2e4\ub978 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \uc0ac\ub77c\uc9c4 \uad00\ub9ac\uc790\ub97c \ucc38\uc870\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc5f0\uacb0\uc744 \ud574\uc81c\ud55c\ub2e4."}, "Assets/03.Scripts/BattleResultManager.cs": {"private void Awake()": "  // \uc774 \ucef4\ud3ec\ub10c\ud2b8\uac00 \ucc98\uc74c \ud65c\uc131\ud654\ub420 \ub54c Unity\uac00 \ud638\ucd9c\ud55c\ub2e4. \uacb0\uacfc \uad00\ub9ac\uc790\ub97c \ub4f1\ub85d\ud558\uace0 \uc804\ud22c \uc2dc\uc791 \ud654\uba74\uc744 \uc900\ube44\ud55c\ub2e4.", "Instance = this;": "  // this\ub294 \uc9c0\uae08 \uc2e4\ud589 \uc911\uc778 \ucef4\ud3ec\ub10c\ud2b8 \uc790\uc2e0\uc774\ub2e4. \ub2e4\ub978 \uc2a4\ud06c\ub9bd\ud2b8\uac00 Instance\ub85c \uc774 \uad00\ub9ac\uc790\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4.", "if (victoryPanel != null)": "  // Inspector\uc5d0 \uc2b9\ub9ac \ud328\ub110\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc744 \ub54c\ub9cc \ubc14\ub85c \uc544\ub798 \uc904\uc744 \uc2e4\ud589\ud55c\ub2e4.", "victoryPanel.SetActive(false);": "  // \uc2b9\ub9ac \ud328\ub110\uc744 \ube44\ud65c\uc131\ud654\ud574 \ud654\uba74\uc5d0\uc11c \uc228\uae34\ub2e4.", "if (defeatPanel != null)": "  // \ud328\ubc30 \ud328\ub110\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \ud655\uc778\ud574 \ube48 \ucc38\uc870\uc5d0\uc11c \ud568\uc218\ub97c \ud638\ucd9c\ud558\ub294 \uc624\ub958\ub97c \ub9c9\ub294\ub2e4.", "defeatPanel.SetActive(false);": "  // \uc804\ud22c\uac00 \uc2dc\uc791\ub420 \ub54c \ud328\ubc30 \ud654\uba74\uc774 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ud55c\ub2e4.", "if (rewardPanel != null)": "  // \ubcf4\uc0c1 \ud328\ub110\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc744 \ub54c\ub9cc \ucd08\uae30 \uc0c1\ud0dc\ub97c \uc124\uc815\ud55c\ub2e4.", "rewardPanel.SetActive(false);": "  // \uc804\ud22c\uac00 \uc2dc\uc791\ub418\uba74 \ubcf4\uc0c1 \uc120\ud0dd \ubc84\ud2bc\ub3c4 \ud328\ub110\uacfc \ud568\uaed8 \uc228\uae34\ub2e4.", "public void ShowVictory()": "  // \uc801 HP\uac00 0\uc774 \ub418\uc5c8\uc744 \ub54c EnemyHealth\uac00 \ud638\ucd9c\ud558\ub294 \uc2b9\ub9ac \ucc98\ub9ac \ud568\uc218\ub2e4.", "if (IsBattleEnded)": "  // \uc774\ubbf8 \uc2b9\ud328\uac00 \uc815\ud574\uc84c\ub2e4\uba74 \uc544\ub798\uc758 return\uc73c\ub85c \ub450 \ubc88\uc9f8 \uacb0\uacfc \ucc98\ub9ac\ub97c \ub9c9\ub294\ub2e4.", "IsBattleEnded = true;": "  // \uc774\ubc88 \uc804\ud22c\uac00 \ub05d\ub0ac\ub2e4\uace0 \uae30\ub85d\ud574 \uc774\ud6c4\uc758 \uc2b9\ud328 \uc694\uccad\uc744 \ub9c9\ub294\ub2e4.", "ShowPanel(victoryPanel);": "  // \uc801\uc774 \uc4f0\ub7ec\uc84c\uc744 \ub54c \uc2b9\ub9ac \ud328\ub110\uc744 \ud654\uba74 \ub9e8 \uc55e\uc73c\ub85c \uac00\uc838\uc628\ub2e4.", "StartCoroutine(OpenRewardPanel());": "  // \uc2b9\ub9ac \ud654\uba74\uc744 \uc7a0\uc2dc \ubcf4\uc5ec\uc900 \ub4a4 \ubcf4\uc0c1 \ud328\ub110\uc744 \uc5ec\ub294 \uc791\uc5c5\uc744 \uc2dc\uc791\ud55c\ub2e4.", "public void ShowDefeat()": "  // \ud50c\ub808\uc774\uc5b4 HP\uac00 0\uc774 \ub418\uc5c8\uc744 \ub54c PlayerHP\uac00 \ud638\ucd9c\ud558\ub294 \ud328\ubc30 \ucc98\ub9ac \ud568\uc218\ub2e4.", "ShowPanel(defeatPanel);": "  // \ud50c\ub808\uc774\uc5b4\uac00 \uc4f0\ub7ec\uc9c0\uba74 \ud328\ubc30 \ud328\ub110\uc744 \ud45c\uc2dc\ud55c\ub2e4.", "StartCoroutine(MoveToDefeatScene());": "  // \ud328\ubc30 \ud328\ub110\uc744 \ubcf4\uc5ec\uc900 \ub4a4 \ud328\ubc30 \uc52c\uc73c\ub85c \uc774\ub3d9\ud558\ub294 \uc791\uc5c5\uc744 \uc2dc\uc791\ud55c\ub2e4.", "private void ShowPanel(GameObject panel)": "  // \uc804\ub2ec\ubc1b\uc740 \ud328\ub110\uc744 \ucf1c\uace0 \uac19\uc740 \ubd80\ubaa8 \uc544\ub798 \ub2e4\ub978 UI\ubcf4\ub2e4 \uc55e\uc5d0 \ud45c\uc2dc\ud55c\ub2e4.", "if (panel == null)": "  // \ud45c\uc2dc\ud560 \ud328\ub110\uc774 \uc5f0\uacb0\ub418\uc9c0 \uc54a\uc558\ub2e4\uba74 \ud568\uc218\ub97c \ub05d\ub0b8\ub2e4.", "panel.SetActive(true);": "  // \ud574\ub2f9 \ud328\ub110\uacfc \uadf8 \uc544\ub798\uc758 \ud65c\uc131 \uc790\uc2dd UI\ub97c \ud654\uba74\uc5d0 \ud45c\uc2dc\ud55c\ub2e4.", "panel.transform.SetAsLastSibling();": "  // \ubd80\ubaa8 \uc544\ub798\uc758 \ub9c8\uc9c0\ub9c9 \uc21c\uc11c\ub85c \uc62e\uaca8 \uac19\uc740 Canvas\uc5d0\uc11c \ub098\uc911\uc5d0 \uadf8\ub824\uc9c0\uac8c \ud55c\ub2e4.", "private IEnumerator OpenRewardPanel()": "  // \uc2b9\ub9ac \ud654\uba74\uc744 \ubcf4\uc0c1 \uc120\ud0dd \ud654\uba74\uc73c\ub85c \ubc14\uafb8\ub294 \ucf54\ub8e8\ud2f4\uc774\ub2e4.", "yield return new WaitForSecondsRealtime(transitionDelay);": "  // \uac8c\uc784 \uc18d\ub3c4\uc640 \uad00\uacc4\uc5c6\uc774 \uc9c0\uc815\ud55c \uc2e4\uc81c \uc2dc\uac04\ub9cc\ud07c \uc774 \ucf54\ub8e8\ud2f4\ub9cc \uae30\ub2e4\ub9b0\ub2e4.", "ShowPanel(rewardPanel);": "  // \ub300\uae30\uac00 \ub05d\ub098\uba74 \ud50c\ub808\uc774\uc5b4\uac00 \ubcf4\uc0c1\uc744 \uace0\ub97c \uc218 \uc788\ub3c4\ub85d \ud328\ub110\uc744 \uc5f0\ub2e4.", "private IEnumerator MoveToDefeatScene()": "  // \ud328\ubc30 \ud654\uba74\uc744 \uc7a0\uc2dc \uc720\uc9c0\ud55c \ub4a4 \uc52c\uc744 \uc804\ud658\ud558\ub294 \ucf54\ub8e8\ud2f4\uc774\ub2e4.", "SceneManager.LoadScene(\"08DefeatScene\");": "  // \ud604\uc7ac \uc804\ud22c \uc52c\uc744 \ub2eb\uace0 \ud328\ubc30 \uc52c\uc744 \ubd88\ub7ec\uc628\ub2e4.", "private void OnDestroy()": "  // \uc774 \ucef4\ud3ec\ub10c\ud2b8\uac00 \ud30c\uad34\ub420 \ub54c Unity\uac00 \ud638\ucd9c\ud558\ub294 \uc815\ub9ac \ud568\uc218\ub2e4.", "if (Instance == this)": "  // \uacf5\uc720 \ucc38\uc870\uac00 \uc544\uc9c1 \uc774 \uad00\ub9ac\uc790\ub97c \uac00\ub9ac\ud0ac \ub54c\ub9cc \ube44\uc6b4\ub2e4.", "Instance = null;": "  // \ub2e4\ub978 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \uc0ac\ub77c\uc9c4 \uad00\ub9ac\uc790\ub97c \ucc38\uc870\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc5f0\uacb0\uc744 \ud574\uc81c\ud55c\ub2e4."}, "Assets/03.Scripts/ItemUseButton.cs": {"private void Awake()": "  // \uc778\ubca4\ud1a0\ub9ac\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \uc544\uc774\ud15c \ubc84\ud2bc\uc5d0 \uc0ac\uc6a9 \ud568\uc218\ub97c \uc5f0\uacb0\ud55c\ub2e4.", "button.onClick.AddListener(UseItem);": "  // \ud50c\ub808\uc774\uc5b4\uac00 \uc774 \ubc84\ud2bc\uc744 \ub204\ub974\uba74 UseItem\uc774 \ud638\ucd9c\ub418\ub3c4\ub85d \ub4f1\ub85d\ud55c\ub2e4.", "public void UseItem()": "  // \uc0ac\uc6a9 \uac00\ub2a5\ud55c \uc0c1\ud0dc\uc778\uc9c0 \ud655\uc778\ud558\uace0 \uc544\uc774\ud15c \ud6a8\uacfc\uac00 \uc801\uc6a9\ub418\uba74 \ud574\ub2f9 \uc2ac\ub86f\uc744 \ube44\uc6b4\ub2e4.", "if (!player.Heal(itemData.effectValue))": "  // \ucd5c\ub300 \uccb4\ub825 \ub4f1\uc73c\ub85c \ud68c\ubcf5\uc5d0 \uc2e4\ud328\ud558\uba74 \ud3ec\uc158\uc744 \uadf8\ub300\ub85c \ub454\ub2e4.", "inventory.RemoveItem(gameObject);": "  // \ud68c\ubcf5\uc5d0 \uc131\uacf5\ud588\uc73c\ubbc0\ub85c \ud074\ub9ad\ud55c \ud3ec\uc158\uc744 \uc2ac\ub86f\uacfc \uc800\uc7a5 \ubaa9\ub85d\uc5d0\uc11c \uc81c\uac70\ud55c\ub2e4.", "private void OnDestroy()": "  // \uc774 \ucef4\ud3ec\ub10c\ud2b8\uac00 \ud30c\uad34\ub420 \ub54c Unity\uac00 \ud638\ucd9c\ud558\ub294 \uc815\ub9ac \ud568\uc218\ub2e4.", "button.onClick.RemoveListener(UseItem);": "  // \ubc84\ud2bc\uc5d0 \ub4f1\ub85d\ud588\ub358 \uc544\uc774\ud15c \uc0ac\uc6a9 \ud568\uc218\ub97c \ud574\uc81c\ud55c\ub2e4."}, "Assets/03.Scripts/EnemyHealth.cs": {"void Awake()": "  // \uc801 \ud504\ub9ac\ud339\uc774 \uc0dd\uc131\ub420 \ub54c Inspector\uc758 \ucd5c\ub300 HP\ub85c \uc804\ud22c\ub97c \uc2dc\uc791\ud55c\ub2e4.", "UpdateHPText();": "  // \ubc29\uae08 \uc124\uc815\ud55c \uccb4\ub825 \uc218\uce58\ub85c \ud654\uba74 \ud45c\uc2dc\ub3c4 \uac31\uc2e0\ud55c\ub2e4.", "private void UpdateHPText()": "  // \ud604\uc7ac \uccb4\ub825\uacfc \ucd5c\ub300 \uccb4\ub825\uc744 \ud654\uba74\uc758 HP \ud14d\uc2a4\ud2b8\uc5d0 \ubc18\uc601\ud55c\ub2e4.", "public void TakeDamage(int damage)": "  // \ubc1b\uc740 \ud53c\ud574\ub97c \uccb4\ub825\uc5d0 \uc801\uc6a9\ud558\uace0 HP\uac00 0\uc774 \ub418\uba74 \uc804\ud22c \uacb0\uacfc\ub97c \uc54c\ub9b0\ub2e4.", "currentHP -= Mathf.Max(0, damage);": "  // \uc74c\uc218 \ud53c\ud574\ub294 0\uc73c\ub85c \ucc98\ub9ac\ud574 \uacf5\uaca9\uc774 \uc801\uc758 \uccb4\ub825\uc744 \ud68c\ubcf5\uc2dc\ud0a4\uc9c0 \uc54a\uac8c \ud55c\ub2e4.", "BattleResultManager.Instance.ShowVictory();": "  // \uc801\uc758 HP\uac00 0\uc774 \ub418\uc5c8\uc74c\uc744 \uc54c\ub824 \uc2b9\ub9ac \ucc98\ub9ac\ub97c \uc2dc\uc791\ud55c\ub2e4."}, "Assets/03.Scripts/BattleNodeButton.cs": {"public void EnterBattle()": "  // \ub178\ub4dc\ub9f5\uc5d0\uc11c BattleNode \ubc84\ud2bc\uc744 \ub20c\ub800\uc744 \ub54c \ud638\ucd9c\ud558\ub294 \ud568\uc218\ub2e4.", "SceneManager.LoadScene(\"04BattleScene\");": "  // \ub178\ub4dc\ub9f5\uc5d0\uc11c \uc804\ud22c \uc52c\uc73c\ub85c \uc774\ub3d9\ud574 \ub2e4\uc74c \uc804\ud22c\ub97c \uc2dc\uc791\ud55c\ub2e4."}, "Assets/03.Scripts/ItemData.cs": {"public int effectValue;": "  // \ud6a8\uacfc\uc758 \uc218\uce58\ub2e4. HealHP \ud3ec\uc158\uc774\uba74 \ud50c\ub808\uc774\uc5b4\uc5d0\uac8c \uc804\ub2ec\ud560 \ud68c\ubcf5\ub7c9\uc774 \ub41c\ub2e4."}, "Assets/03.Scripts/EnemyCard.cs": {"private void Start()": "  // \uc801\uc774 \uc0dd\uc131\ub41c \ub4a4 \ubbf8\ub9ac\ubcf4\uae30 UI\ub97c \ucc3e\uc544 \uccab \ud589\ub3d9\uc744 \uc608\uace0\ud55c\ub2e4.", "public void PrepareNextCard()": "  // \ub2e4\uc74c \uc801 \ud134\uc758 \uce74\ub4dc\ub97c \uc815\ud558\uace0 \ubbf8\ub9ac\ubcf4\uae30\uc5d0 \uac19\uc740 \uce74\ub4dc\ub97c \ud45c\uc2dc\ud55c\ub2e4.", "NextCard = ChooseCard();": "  // \uc9c0\uae08 \ubf51\uc740 \uacb0\uacfc\ub97c \ubcf4\uad00\ud574 \uc2e4\uc81c \ubc18\uaca9\uc5d0\uc11c\ub3c4 \uac19\uc740 \uce74\ub4dc\ub97c \uc0ac\uc6a9\ud55c\ub2e4.", "public CardData ChooseCard()": "  // \uc801\uc758 \uce74\ub4dc \ubaa9\ub85d\uc5d0\uc11c \ube44\uc5b4 \uc788\ub294 \ud56d\ubaa9\uc744 \uc81c\uc678\ud558\uace0 \ubb34\uc791\uc704 \ud55c \uc7a5\uc744 \ubc18\ud658\ud55c\ub2e4.", "int selectedIndex = Random.Range(0, validCount);": "  // \uc720\ud6a8\ud55c \uce74\ub4dc \uc218\ub97c \uae30\uc900\uc73c\ub85c 0\ubd80\ud130 \uac1c\uc218 \ubbf8\ub9cc\uae4c\uc9c0\uc758 \ubc88\ud638\ub97c \ubf51\ub294\ub2e4.", "selectedIndex--;": "  // \ube48 \ud56d\ubaa9\uc744 \uc81c\uc678\ud558\uace0 \ud55c \uc7a5\uc529 \uc9c0\ub098\uac00\uba70 \ubf51\uc740 \uc21c\ubc88\uc744 \ucc3e\ub294\ub2e4."}, "Assets/03.Scripts/PlayerHP.cs": {"private void Awake()": "  // \ud50c\ub808\uc774\uc5b4\uac00 \uc804\ud22c \uc52c\uc5d0 \uc0dd\uc131\ub420 \ub54c \ud604\uc7ac \uccb4\ub825\uacfc HP \ud14d\uc2a4\ud2b8\ub97c \ucd08\uae30\ud654\ud55c\ub2e4.", "UpdateHPText();": "  // \ubc29\uae08 \uc124\uc815\ud55c \uccb4\ub825 \uc218\uce58\ub85c \ud654\uba74 \ud45c\uc2dc\ub3c4 \uac31\uc2e0\ud55c\ub2e4.", "private void UpdateHPText()": "  // \ud604\uc7ac \uccb4\ub825\uacfc \ucd5c\ub300 \uccb4\ub825\uc744 \ud654\uba74\uc758 HP \ud14d\uc2a4\ud2b8\uc5d0 \ubc18\uc601\ud55c\ub2e4.", "public void TakeDamage(int damage)": "  // \ubc1b\uc740 \ud53c\ud574\ub97c \uccb4\ub825\uc5d0 \uc801\uc6a9\ud558\uace0 HP\uac00 0\uc774 \ub418\uba74 \uc804\ud22c \uacb0\uacfc\ub97c \uc54c\ub9b0\ub2e4.", "CurrentHP -= Mathf.Max(0, damage);": "  // \uc74c\uc218 \ud53c\ud574\ub294 \ubb34\uc2dc\ud558\uace0 \uc2e4\uc81c \ubc1b\uc740 \uc591\ub9cc \ud50c\ub808\uc774\uc5b4 HP\uc5d0\uc11c \ube80\ub2e4.", "BattleResultManager.Instance.ShowDefeat();": "  // \ud50c\ub808\uc774\uc5b4 \uc0ac\ub9dd\uc744 \uacb0\uacfc \uad00\ub9ac\uc790\uc5d0\uac8c \uc54c\ub824 \ud328\ubc30 \ucc98\ub9ac\ub97c \uc2dc\uc791\ud55c\ub2e4.", "public bool Heal(int amount)": "  // \ud68c\ubcf5\uc774 \uc801\uc6a9\ub418\uc5c8\ub294\uc9c0 \ubc18\ud658\ud574 \ud3ec\uc158\uc744 \uc18c\ubaa8\ud560\uc9c0 \uacb0\uc815\ud558\uac8c \ud55c\ub2e4.", "CurrentHP = Mathf.Min(CurrentHP + amount, maxHP);": "  // \ud68c\ubcf5\ub7c9\uc744 \ub354\ud558\ub418 \ucd5c\ub300 HP\ub97c \ub118\uc9c0 \uc54a\uac8c \ud55c\ub2e4."}}